区间反转的标准写法是对 `[curr, groupNext)` 这 k 个节点做头插法翻转。代码：

```
prev = groupNext;  // 关键：prev 初始化为 groupNext，不是 null
curr = groupPrev.next;
while (curr != groupNext) {
    next = curr.next;
    curr.next = prev;
    prev = curr;
    curr = next;
}
```

这里 `prev = groupNext` 是一个精妙的设计：
- 反转结束后，prev 指向原组尾（即 kth），它的 next 已经自动接上了 groupNext
- curr 指向 groupNext，循环自然终止
- 整个反转过程就完成了「组内翻转 + 尾部接下一组」两件事，不需要额外的连接代码

如果 `prev = null`，反转后原组尾的 next 变成 null，还要手动接 groupNext，多一步且容易忘。

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head);
        ListNode groupPrev = dummy;

        while (true) {
            // 第 1 步：从 groupPrev 走 k 步，找到当前组第 k 个节点
            ListNode kth = getKth(groupPrev, k);
            if (kth == null) break;  // 剩余不足 k 个，不反转

            // 第 2 步：记录下一组的起始节点
            ListNode groupNext = kth.next;

            // 第 3 步：反转 [groupPrev.next, groupNext) 半开区间
            ListNode prev = groupNext;  // 关键：prev 初始化为 groupNext
            ListNode curr = groupPrev.next;
            while (curr != groupNext) {
                ListNode next = curr.next;
                curr.next = prev;
                prev = curr;
                curr = next;
            }
            // 循环结束后：prev 指向 kth（新组头），kth.next 已接上 groupNext

            // 第 4 步：重连——groupPrev 接新头，groupPrev 移到新组尾
            ListNode oldGroupHead = groupPrev.next;  // 反转前的组头，反转后变成组尾
            groupPrev.next = kth;    // 前一组尾 接 新组头
            groupPrev = oldGroupHead; // groupPrev 移到新组尾，为下一轮准备
        }

        return dummy.next;
    }

    // 从 start 开始向后走 k 步，返回第 k 个节点；不足 k 个返回 null
    private ListNode getKth(ListNode start, int k) {
        ListNode curr = start;
        while (curr != null && k > 0) {
            curr = curr.next;
            k--;
        }
        return curr;
    }
}

func reverseKGroup(head *ListNode, k int) *ListNode {
	dummy := &ListNode{Next: head}
	groupPrev := dummy

	for {
		kth := getKth(groupPrev, k)
		if kth == nil {
			break
		}
		groupNext := kth.Next

		prev := groupNext
		curr := groupPrev.Next
		for curr != groupNext {
			next := curr.Next
			curr.Next = prev
			prev = curr
			curr = next
		}

		oldGroupHead := groupPrev.Next
		groupPrev.Next = kth
		groupPrev = oldGroupHead
	}

	return dummy.Next
}

func getKth(start *ListNode, k int) *ListNode {
	curr := start
	for curr != nil && k > 0 {
		curr = curr.Next
		k--
	}
	return curr
}
